def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # 记录每个值对应的坐标
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # 从值最小的单元格开始
    start_val = 1
    start_i, start_j = pos[start_val]

    # 动态规划：dp[length][cell] = 从该cell出发长度为length的最小路径（列表）
    # 但为了节省空间，我们只保留当前长度和下一长度
    # 初始化长度为1：每个cell的路径就是它自己
    dp = {}
    for i in range(n):
        for j in range(n):
            dp[(i, j)] = [grid[i][j]]

    # 逐步扩展长度
    for length in range(2, k + 1):
        new_dp = {}
        for (i, j), path in dp.items():
            # 尝试所有邻居
            for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    new_path = [grid[ni][nj]] + path
                    key = (ni, nj)
                    if key not in new_dp or new_path < new_dp[key]:
                        new_dp[key] = new_path
        dp = new_dp

    # 找到所有长度为k的路径中字典序最小的
    best = None
    for path in dp.values():
        if best is None or path < best:
            best = path
    return best
